    printf("%d",foo(A,9));
    return 0;
}

typedef struct list {
    int data;
    struct list *next;
} LIST;

int find (int query, LIST *list) {
    while (list != NULL){
        if(list->data == query) return 1;
        list = list->next;
    }
    return 0;
}
